    override val dlg_zero_telemetry_title = "Senda Privacy Statement:"
    override val dlg_zero_telemetry_content = "1. Zero Telemetry: Senda does not transmit any analytical data or habits metrics.\n\n2. Zero Remote Studies: No A/B testing or experiments are injected into your browser.\n\n3. Zero Device Identifiers: No unique device ID is created for your phone.\n\n4. Local Control: Your bookmarks, passwords, and history live only on your device."
    override val dlg_about_content = "Lightweight, fast and private web browser powered by Mozilla's GeckoView. Built to provide seamless navigation, robust security and total respect for your privacy."
    override val dlg_about_senda_build = "Senda Browser\nVersion 0.1.0-alpha (Build 1)"
    override val dlg_about_license_details = "License: GNU General Public License v3 (GPLv3)\nArchitecture: GeckoView GeckoRuntime Native\nPlatform: Android (64-bit)"
    override val dlg_about_third_party = "Senda integrates world-class free and open-source components:\n\n• GeckoView (Mozilla Public License 2.0)\n• Jetpack Compose & AndroidX (Apache License 2.0)\n• Kotlin & Coroutines (Apache License 2.0)\n• HiddenApiBypass (Apache License 2.0)\n• uBlock Origin (GNU GPL v3)\n• Tor, tor-android, jtorctl (BSD 3-Clause)\n• Wallpapers from Debian, GNU, Gentoo, KDE, GNOME, Fedora, Arch and Xfce (GPL, CC BY-SA, CC0)"
    override val dlg_privacy_principles = "Senda Privacy Principles:\n\n1. Your attention belongs to you: No invasive content, manipulative ads or corporate retention algorithms.\n\n2. Your device is yours: Zero silent telemetry and zero covert data collection.\n\n3. Open & Free Web: Support for open-source software and a decentralized, independent web."
    override val dlg_reader_mode_desc = "Transforms any web article into a clean reading view, removing ads, trackers, banners, and clutter."
    override val dlg_translations_title = "Page Translation"
