    override val dlg_privacy_principles = "Principios de Privacidad de Senda:\n\n1. Tu atención te pertenece: Sin contenido invasivo, anuncios manipuladores ni algoritmos de retención corporativos.\n\n2. Tu dispositivo es tuyo: Cero telemetría silenciosa y cero recolección encubierta de tus datos de navegación.\n\n3. Web Abierta y Libre: Apoyo al software de código abierto y a una web descentralizada e independiente."
