    override val dlg_zero_telemetry_title = "Déclaration de Confidentialité Senda :"
    override val dlg_zero_telemetry_content = "1. Zéro Télémétrie : Senda n'envoie aucune donnée d'analyse ni métrique d'utilisation.\n\n2. Aucune Étude Distante : Aucune expérimentation A/B n'est injectée dans votre navigateur.\n\n3. Aucun Identifiant d'Appareil : Aucun identifiant unique n'est créé pour votre téléphone.\n\n4. Contrôle Local : Vos favoris, mots de passe et votre historique restent exclusivement sur votre appareil."
    override val dlg_about_content = "Navigateur web léger, rapide et privé avec le moteur GeckoView de Mozilla. Conçu pour une navigation fluide, une sécurité robuste et le respect total de votre vie privée."
