    override val dlg_about_license_details = "Licence : GNU General Public License v3 (GPLv3)\nArchitecture : GeckoView GeckoRuntime Natif\nPlateforme : Android (64-bit)"
    override val dlg_about_third_party = "Senda intègre des composants libres de premier plan :\n\n• GeckoView (Mozilla Public License 2.0)\n• Jetpack Compose & AndroidX (Apache License 2.0)\n• Kotlin & Coroutines (Apache License 2.0)\n• HiddenApiBypass (Apache License 2.0)\n• uBlock Origin (GNU GPL v3)\n• Tor, tor-android, jtorctl (BSD 3-Clause)\n• Fonds d'écran de Debian, GNU, Gentoo, KDE, GNOME, Fedora, Arch et Xfce (GPL, CC BY-SA, CC0)"
    override val dlg_privacy_principles = "Principes de Confidentialité de Senda :\n\n1. Votre attention vous appartient : Pas de publicités manipulatrices ni d'algorithmes de rétention.\n\n2. Votre appareil est à vous : Zéro télémétrie silencieuse et zéro collecte de données dissimulée.\n\n3. Web Ouvert et Libre : Soutien aux logiciels libres et à un web décentralisé."
