    override val dlg_zero_telemetry_title = "Declaração de Privacidade Senda:"
    override val dlg_zero_telemetry_content = "1. Zero Telemetria: O Senda não envia nenhum pacote analítico nem métricas de uso.\n\n2. Zero Estudos Remotos: Nenhum experimento A/B é injetado no seu navegador.\n\n3. Zero Identificadores de Dispositivo: Nenhum ID exclusivo é gerado para o seu aparelho.\n\n4. Controle Local: Seus favoritos, senhas e histórico existem apenas no seu dispositivo."
    override val dlg_about_content = "Navegador web leve, rápido e privado com motor GeckoView da Mozilla. Criado para oferecer navegação fluida, segurança robusta e respeito integral à sua privacidade."
