    override val dlg_zero_telemetry_title = "Senda 隐私权利保护宣言："
    override val dlg_zero_telemetry_content = "1. 零遥测记录：Senda 坚决不上传任何使用分析数据或用户行为统计。\n\n2. 零远程实验：绝不在您的浏览器中强行注入任何远程 A/B 测试或实验代码。\n\n3. 零设备标识：绝不针对您的手机生成任何全局唯一的广告或设备追踪标识符。\n\n4. 本地全权掌控：您的个人书签、加密密码与浏览历史仅保存在您的个人设备中。"
    override val dlg_about_content = "基于 Mozilla GeckoView 原生引擎打造的轻量、高速且高度注重隐私保护的网络浏览器。致力于为您提供无缝流畅的浏览体验与极致的数字安全保障。"
    override val dlg_about_senda_build = "Senda 浏览器\n版本 0.1.0-alpha (Build 1)"
